WITH payload AS (SELECT $payload$[{"name": "伊勢信仰", "slug": "ise-shinko", "description": "伊勢信仰に関わる信仰。"}, {"name": "伊弉諾信仰", "slug": "izanagi-shinko", "description": "伊弉諾信仰に関わる信仰。"}, {"name": "住吉信仰", "slug": "sumiyoshi-shinko", "description": "住吉信仰に関わる信仰。"}, {"name": "八幡信仰", "slug": "hachiman-shinko", "description": "八幡信仰に関わる信仰。"}, {"name": "出羽三山信仰", "slug": "dewasanzan-shinko", "description": "出羽三山信仰に関わる信仰。"}, {"name": "出雲系信仰", "slug": "izumo-kei-shinko", "description": "出雲系信仰に関わる信仰。"}, {"name": "天神信仰", "slug": "tenjin-shinko", "description": "天神信仰に関わる信仰。"}, {"name": "宗像信仰", "slug": "munakata-shinko", "description": "宗像信仰に関わる信仰。"}, {"name": "日本武尊信仰", "slug": "yamato-takeru-shinko", "description": "日本武尊信仰に関わる信仰。"}, {"name": "春日信仰", "slug": "kasuga-shinko", "description": "春日信仰に関わる信仰。"}, {"name": "氷川信仰", "slug": "hikawa-shinko", "description": "氷川信仰に関わる信仰。"}, {"name": "浅間信仰", "slug": "asama-shinko", "description": "浅間信仰に関わる信仰。"}, {"name": "熊野信仰", "slug": "kumano-shinko", "description": "熊野信仰に関わる信仰。"}, {"name": "祇園信仰", "slug": "gion-shinko", "description": "祇園信仰に関わる信仰。"}, {"name": "稲荷信仰", "slug": "inari-shinko", "description": "稲荷信仰に関わる信仰。"}, {"name": "若狭信仰", "slug": "wakasa-shinko", "description": "若狭信仰に関わる信仰。"}, {"name": "諏訪信仰", "slug": "suwa-shinko", "description": "諏訪信仰に関わる信仰。"}, {"name": "賀茂信仰", "slug": "kamo-shinko", "description": "賀茂信仰に関わる信仰。"}, {"name": "鷲宮信仰", "slug": "washinomiya-shinko", "description": "鷲宮信仰に関わる信仰。"}, {"name": "鹿島信仰", "slug": "kashima-shinko", "description": "鹿島信仰に関わる信仰。"}]$payload$::jsonb AS value), lineage_data AS (SELECT * FROM jsonb_to_recordset((SELECT value FROM payload)) AS x(name text,slug text,description text)), lineage_upsert AS (INSERT INTO public.lineages(name,slug,description,is_published) SELECT x.name,x.slug,x.description,true FROM lineage_data x WHERE NOT EXISTS (SELECT 1 FROM public.lineages old WHERE old.slug=x.slug OR old.name=x.name) ON CONFLICT (slug) DO UPDATE SET is_published=true RETURNING id) SELECT jsonb_build_object('new_lineages',(SELECT count(*) FROM lineage_upsert)) AS inserted;